(708617, 75637, 8139, '<td valign="top">I like dark compositions. And empty spaces. 10.</td>', 'I like dark compositions. And empty spaces. 10.', '2004-05-10 10:55:51.000000', NULL, 1),
(708620, 75541, 20577, '<td valign="top">Love it! The positioning of the couple is perfect. 9</td>', 'Love it! The positioning of the couple is perfect. 9', '2004-05-10 10:57:00.000000', NULL, 1),
