(709655, 75349, 327, '<td valign="top">Looks heavenly. Wonderful lens, light and colors.</td>', 'Looks heavenly. Wonderful lens, light and colors.', '2004-05-10 19:07:31.000000', NULL, 1),
(709656, 74665, 327, '<td valign="top">I do see elves. :) Lovely.</td>', 'I do see elves. :) Lovely.', '2004-05-10 19:08:00.000000', NULL, 1),
(709658, 75185, 327, '<td valign="top">Great looking tones/and focus. Well done.</td>', 'Great looking tones/and focus. Well done.', '2004-05-10 19:08:26.000000', NULL, 1),
(709660, 75538, 327, '<td valign="top">What a veiw....nice one.</td>', 'What a veiw....nice one.', '2004-05-10 19:09:11.000000', NULL, 1),
