(709665, 74361, 327, '<td valign="top">Wonderfurl focus/lens work. Love it. Great poster.</td>', 'Wonderfurl focus/lens work. Love it. Great poster.', '2004-05-10 19:10:39.000000', NULL, 1),
(709667, 75204, 5792, '<td valign="top">Lighting, color, contrast and content are exceptional. The solid white background works especailly well for this image. Should be in the hunt for a ribbon.</td>', 'Lighting, color, contrast and content are exceptional. The solid white background works especailly well for this image. Should be in the hunt for a ribbon.', '2004-05-10 19:11:05.000000', NULL, 1),
