INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(712262, 74290, 20204, '<td valign="top">Ohh, if  only your reflection wasn''t in the water!  This is creative.</td>', 'Ohh, if  only your reflection wasn''t in the water!  This is creative.', '2004-05-11 19:58:58.000000', NULL, 1),
(712263, 75090, 20204, '<td valign="top">The subject is out of focus,</td>', 'The subject is out of focus,', '2004-05-11 20:00:09.000000', NULL, 1),
(712301, 75369, 20115, '<td valign="top">very magical</td>', 'very magical', '2004-05-11 20:41:59.000000', NULL, 1),
(712375, 74665, 8054, '<td valign="top">I really like this shot. Nice sky, water, trees and the fog. All of those elements are well composed. Now, things I would fix: cropping and maybe levels. Look in the corners for the dark portions (vignette). Crop those out as well as the misc tree parts in the lower right. Oh heck, and the one on the right middle, too, the one that''s all by itself in the fog. Fiddle with the levels to increase contrast a bit and this would be an amazing image! 7</td>', 'I really like this shot. Nice sky, water, trees and the fog. All of those elements are well composed. Now, things I would fix: cropping and maybe levels. Look in the corners for the dark portions (vignette). Crop those out as well as the misc tree parts in the lower right. Oh heck, and the one on the right middle, too, the one that''s all by itself in the fog. Fiddle with the levels to increase contrast a bit and this would be an amazing image! 7', '2004-05-11 21:22:59.000000', NULL, 1),
(712378, 74763, 8054, '<td valign="top">This just needs a little lopped off the left side and the it''d be perfect. The sparks falling down are good so the bottom of the image is needed. Nice job! 7</td>', 'This just needs a little lopped off the left side and the it''d be perfect. The sparks falling down are good so the bottom of the image is needed. Nice job! 7', '2004-05-11 21:25:00.000000', NULL, 1),
(712382, 75185, 8054, '<td valign="top">Well done with b/w and DOF. Good job cropping, too. One thing confuses me and that''s the upper right corner. Why is that group of "spines" blurry and the ones below not blurry? 7</td>', 'Well done with b/w and DOF. Good job cropping, too. One thing confuses me and that''s the upper right corner. Why is that group of "spines" blurry and the ones below not blurry? 7', '2004-05-11 21:29:38.000000', NULL, 1),
(712387, 74676, 8054, '<td valign="top">Interesting subject to say the least. Very patriotic colors. Good details on the tarp and nice contrast. Overall, image seems to have been slightly oversharpened but it''s not distracting. 7</td>', 'Interesting subject to say the least. Very patriotic colors. Good details on the tarp and nice contrast. Overall, image seems to have been slightly oversharpened but it''s not distracting. 7', '2004-05-11 21:31:51.000000', NULL, 1),
(712391, 75315, 8054, '<td valign="top">Too bad we can''t see the faces. But it''s an action shot so it''s (mostly) understandable. Contrast seems a bit weak so maybe try adjusting the levels. Nice details throughout.</td>', 'Too bad we can''t see the faces. But it''s an action shot so it''s (mostly) understandable. Contrast seems a bit weak so maybe try adjusting the levels. Nice details throughout.', '2004-05-11 21:36:35.000000', NULL, 1),
(712393, 75501, 8054, '<td valign="top">OK, your title is "Carl Sandburg House" yet your primary focus is on the grapevine/ivy/plant. Try reversing the focus point or changing the title. Ignoring the title altogether, the house is overexposed and the plant is underexposed slightly. The leaves are in focus, however.</td>', 'OK, your title is "Carl Sandburg House" yet your primary focus is on the grapevine/ivy/plant. Try reversing the focus point or changing the title. Ignoring the title altogether, the house is overexposed and the plant is underexposed slightly. The leaves are in focus, however.', '2004-05-11 21:40:22.000000', NULL, 1),
(712395, 75565, 8054, '<td valign="top">I don''t see the connection between WTC (from the title) and the image itself. The photo is also a bit washed out contrast-wise.</td>', 'I don''t see the connection between WTC (from the title) and the image itself. The photo is also a bit washed out contrast-wise.', '2004-05-11 21:41:59.000000', NULL, 1),
(712399, 74919, 8054, '<td valign="top">Very moving photo! I really like the use of a vanishing point here as it works VERY well. I also like the use of sepia. My only complaints are the focusing seems a bit soft and the contrast is weak.</td>', 'Very moving photo! I really like the use of a vanishing point here as it works VERY well. I also like the use of sepia. My only complaints are the focusing seems a bit soft and the contrast is weak.', '2004-05-11 21:44:23.000000', NULL, 1),
(712410, 75305, 19117, '<td valign="top">quiet, maybe?</td>', 'quiet, maybe?', '2004-05-11 21:52:43.000000', NULL, 1),
(712411, 75438, 19117, '<td valign="top">Our very own star -- beautiful!</td>', 'Our very own star -- beautiful!', '2004-05-11 21:55:04.000000', NULL, 1),
