(720453, 75100, 9821, '<td valign="top">great colors ... 9</td>', 'great colors ... 9', '2004-05-15 22:35:33.000000', NULL, 1),
(720455, 74866, 20204, '<td valign="top">Great background - compliments the subject nicely.  I like the colors in this as well as the nice balanced feel.  You have composed it very well - nice job!</td>', 'Great background - compliments the subject nicely.  I like the colors in this as well as the nice balanced feel.  You have composed it very well - nice job!', '2004-05-15 22:36:12.000000', NULL, 1),
